-- Passage rg6-story-details-inference-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('8403ebd8-b34c-5112-a015-4b3ba9e578c6', 'rg6-story-details-inference-p06', (select id from public.skills where slug = 'read-g6-story-details-inference'), null,
        '6-8', $q$The First Bowl$q$, $q$My first bowl leaned like a tired flower.
Its rim rose high on one side, low on the other,
and a thumbprint sat in the bottom
where I had pressed too hard.

Ms. Adebayo turned it slowly in her hands.
She did not say that it was perfect.
She said, "The wheel was moving faster than your fingers.
Next time, slow the wheel, not your hands."

I made eleven bowls that winter.
Seven collapsed before they ever saw the kiln.
Two cracked in the fire with a sound like ice on a pond.
One came out almost round.

The last one, the eleventh,
sits on my grandmother's table now
and holds the lemons she buys on Sundays.
She tells her visitors that I made it.
She does not tell them about the other ten.

But I keep the first one on my windowsill,
leaning toward the light,
with my thumbprint still in the bottom
like a note I wrote to myself.$q$, 'draft')
